import{_ as e,c as o,o as c,am as t}from"./chunks/framework.BJtUKP3U.js";const s=JSON.parse('{"title":"Pogget_Std 个性化字段表","description":"","frontmatter":{"prev":{"text":"预设文件与继承","link":"/docs/pogget/custom-vina/presets"},"next":{"text":"宿主输入","link":"/docs/pogget/custom-vina/inputs"}},"headers":[],"relativePath":"docs/pogget/custom-vina/standard-fields.md","filePath":"docs/pogget/custom-vina/standard-fields.md"}'),r={name:"docs/pogget/custom-vina/standard-fields.md"};function a(i,d,n,u,l,b){return c(),o("div",null,d[0]||(d[0]=[t('<h1 id="pogget-std-个性化字段表" tabindex="-1">Pogget_Std 个性化字段表 <a class="header-anchor" href="#pogget-std-个性化字段表" aria-label="Permalink to &quot;Pogget_Std 个性化字段表&quot;">​</a></h1><p>本页逐项对应 <code>Pogget_Std.vina</code> 的个性化控件。表中的完整路径可用作 <code>Preset.parentValues</code> 的键；表达式读取时在后面加 <code>.value</code>，例如 <code>${Background.ui.CornerRadius.value}</code>。界面按“背景、标签、图标、行为”四组排列。</p><p><code>number</code> 是有限数值，<code>boolean</code> 必须写 <code>true</code> 或 <code>false</code>，<code>text</code> 是带引号的字符串。<code>choice</code> 是下拉选项，<code>slider</code> 是滑条，<code>switch</code> 是开关，<code>font</code> 是字体选择器，<code>color</code> 使用 <code>0..16777215</code> 的整数 COLORREF（可写 <code>rgb(r, g, b)</code>）。布尔选项请填写真实布尔值；菜单顺序与存储值不一定相同。</p><p><code>rgb(...)</code> 可用于普通 <code>ui.default</code> 或 <code>view</code> 表达式；<code>parentValues</code> 只接受字面量，颜色请换算成整数 <code>r + 256 * g + 65536 * b</code> 后填写，例如纯红色是 <code>255</code>。</p><p>滑条的取值范围、步长如下；不透明度用 <code>0..1</code> 表示，<code>0</code> 完全透明、<code>1</code> 完全不透明。两端可直接取到最小值和最大值，即使步长不能整除范围。表中默认值是未保存过参数时的默认；已有配置会覆盖普通 <code>ui.default</code>。<a href="./presets.html#为父预设指定参数">父预设参数</a>会建立当前子预设独立的参数值。</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><table tabindex="0"><thead><tr><th>完整字段路径 / 界面项目</th><th>类型 / 控件</th><th>默认值</th><th>值、范围与选项</th><th>原生配置绑定</th></tr></thead><tbody><tr><td><code>Background.ui.RenderStyle</code><br>渲染样式</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：默认；<code>1</code>：静态材质层（兼容）；<code>2</code>：模糊 (D3D11)；<code>3</code>：透明 (D3D11)；<code>4</code>：扩展（D3D11）</td><td><code>CompatibleLayer</code></td></tr><tr><td><code>Background.ui.BackgroundColor</code><br>背景颜色</td><td><code>number</code> / <code>color</code></td><td><code>0</code></td><td>整数 <code>0..16777215</code>，COLORREF；<code>rgb(r, g, b)</code></td><td><code>BackgroundColor</code></td></tr><tr><td><code>Background.ui.BackgroundOpacity</code><br>背景不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>1</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td><code>bgAlpha</code></td></tr><tr><td><code>Background.ui.DwmCorner</code><br>圆角合成</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：小圆角（默认）；<code>1</code>：正常圆角</td><td><code>DwmCornerPreference</code></td></tr><tr><td><code>Background.ui.CornerRadius</code><br>窗口圆角大小:</td><td><code>number</code> / <code>slider</code></td><td><code>16</code></td><td><code>0..20</code>，步长 <code>1</code></td><td><code>cornerRad</code></td></tr><tr><td><code>Background.ui.StaticLayer</code><br>启用静态材质层</td><td><code>boolean</code> / <code>switch</code></td><td><code>false</code></td><td><code>false</code>：关闭；<code>true</code>：开启</td><td><code>EnableStaticMaterialLayerForD3D11</code></td></tr><tr><td><code>Background.ui.ShadowBlur</code><br>阴影模糊度:</td><td><code>number</code> / <code>slider</code></td><td><code>16</code></td><td><code>0..32</code>，步长 <code>1</code></td><td><code>shadowBlur</code></td></tr><tr><td><code>Background.ui.ShadowOpacity</code><br>阴影不透明度:</td><td><code>number</code> / <code>slider</code></td><td><code>0.2</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td><code>shadowAlpha</code></td></tr><tr><td><code>Background.ui.ShadowX</code><br>阴影偏移 X:</td><td><code>number</code> / <code>slider</code></td><td><code>0</code></td><td><code>-32..32</code>，步长 <code>1</code></td><td><code>shadowOffsetX</code></td></tr><tr><td><code>Background.ui.ShadowY</code><br>阴影偏移 Y:</td><td><code>number</code> / <code>slider</code></td><td><code>4</code></td><td><code>-32..32</code>，步长 <code>1</code></td><td><code>shadowOffsetY</code></td></tr><tr><td><code>Background.ui.WindowBorder</code><br>窗口边框</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：无边框（默认）；<code>1</code>：画布；<code>2</code>：原生边框；<code>3</code>：高光；扩展层 <code>4</code> 的菜单不提供原生边框 <code>2</code></td><td><code>TransparentFrameMode</code></td></tr><tr><td><code>Background.ui.BorderColor</code><br>边框颜色</td><td><code>number</code> / <code>color</code></td><td><code>0</code></td><td>整数 <code>0..16777215</code>，COLORREF；<code>rgb(r, g, b)</code></td><td><code>BorderColor</code></td></tr><tr><td><code>Background.ui.BorderOpacity</code><br>边框不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>1</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td><code>BorderOpacity</code></td></tr></tbody></table><h2 id="标签与标题" tabindex="-1">标签与标题 <a class="header-anchor" href="#标签与标题" aria-label="Permalink to &quot;标签与标题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>完整字段路径 / 界面项目</th><th>类型 / 控件</th><th>默认值</th><th>值、范围与选项</th><th>原生配置绑定</th></tr></thead><tbody><tr><td><code>Tag.ui.TitleStyle</code><br>标签样式</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：VinaUI（默认）；<code>1</code>：悬浮；<code>2</code>：胶囊</td><td><code>TitleType</code></td></tr><tr><td><code>Tag.ui.TitleColor</code><br>标题栏颜色</td><td><code>number</code> / <code>color</code></td><td><code>0</code></td><td>整数 <code>0..16777215</code>，COLORREF；<code>rgb(r, g, b)</code></td><td><code>TitleBarColor</code></td></tr><tr><td><code>Tag.ui.TitleOpacity</code><br>标题栏不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>1</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td><code>titleAlpha</code></td></tr><tr><td><code>Tag.ui.TitleBlur</code><br>模糊半径</td><td><code>number</code> / <code>slider</code></td><td><code>-1</code></td><td><code>0..32</code>，步长 <code>1</code>；默认 <code>-1</code> 为自动：默认/静态层取 <code>14</code>，模糊/透明/扩展层取 <code>5</code></td><td><code>TitleBlurRadius</code></td></tr><tr><td><code>Tag.ui.TagOpacity</code><br>标签不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>1</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td><code>tagAlpha</code></td></tr><tr><td><code>Tag.ui.TagTextOpacity</code><br>标签文本不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>1</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td><code>tagTextAlpha</code></td></tr><tr><td><code>Tag.ui.TagStyle</code><br>颜色标签样式</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：贴纸（默认）；<code>1</code>：描边；<code>2</code>：荧光笔；<code>3</code>：无装饰；<code>4</code>：文本</td><td><code>TagStyle</code></td></tr><tr><td><code>Tag.ui.TagFont</code><br>标签字体</td><td><code>text</code> / <code>font</code></td><td><code>&quot;Segoe UI&quot;</code></td><td>字体族名称，例如 <code>&quot;Segoe UI&quot;</code>、<code>&quot;微软雅黑&quot;</code></td><td><code>tagFontFamily</code></td></tr></tbody></table><h2 id="图标" tabindex="-1">图标 <a class="header-anchor" href="#图标" aria-label="Permalink to &quot;图标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>完整字段路径 / 界面项目</th><th>类型 / 控件</th><th>默认值</th><th>值、范围与选项</th><th>原生配置绑定</th></tr></thead><tbody><tr><td><code>VinaIcon.ui.FolderView</code><br>文件夹视图</td><td><code>boolean</code> / <code>choice</code></td><td><code>false</code></td><td><code>false</code>：显示文件夹预览（默认）；<code>true</code>：显示系统图标</td><td><code>ShowDefaultFolderIcon</code></td></tr><tr><td><code>VinaIcon.ui.TextPreview</code><br>文本预览视图</td><td><code>boolean</code> / <code>choice</code></td><td><code>true</code></td><td><code>true</code>：显示文本预览（默认）；<code>false</code>：显示系统图标</td><td><code>ShowTextPreview</code></td></tr><tr><td><code>VinaIcon.ui.MediaPreview</code><br>媒体预览视图</td><td><code>boolean</code> / <code>choice</code></td><td><code>true</code></td><td><code>true</code>：显示媒体预览（默认）；<code>false</code>：显示系统图标</td><td><code>ShowMediaPreview</code></td></tr><tr><td><code>VinaIcon.ui.FileName</code><br>文件名称</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：显示文件扩展名（默认）；<code>1</code>：隐藏文件扩展名；<code>2</code>：不显示文件名</td><td><code>HideFileExtension</code></td></tr><tr><td><code>VinaIcon.ui.FileNameColor</code><br>文件名颜色</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：主题（默认）；<code>1</code>：白色；<code>2</code>：黑色</td><td><code>FileNameColorMode</code></td></tr><tr><td><code>VinaIcon.ui.TextShadow</code><br>文本阴影</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：无阴影（默认）；<code>1</code>：厚阴影；<code>2</code>：浅阴影；<code>3</code>：主题色阴影</td><td><code>TextRenderMode</code></td></tr><tr><td><code>VinaIcon.ui.ListDetails</code><br>列表详细信息</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：文件大小（默认）；<code>1</code>：无；<code>2</code>：修改日期</td><td><code>ListDetailType</code></td></tr><tr><td><code>VinaIcon.ui.Font</code><br>字体选择</td><td><code>text</code> / <code>font</code></td><td><code>&quot;Segoe UI&quot;</code></td><td>字体族名称，例如 <code>&quot;Segoe UI&quot;</code>、<code>&quot;微软雅黑&quot;</code></td><td><code>fontFamily</code></td></tr><tr><td><code>VinaIcon.ui.TextSize</code><br>文本大小: 100% (默认)</td><td><code>number</code> / <code>slider</code></td><td><code>10</code></td><td><code>6..18</code>，步长 <code>0.5</code>；<code>10</code> 对应界面 <code>100%</code>，<code>6..18</code> 对应 <code>60%..180%</code></td><td><code>textSize</code></td></tr><tr><td><code>VinaIcon.ui.TextOmit</code><br>文字省略: 当前基准</td><td><code>number</code> / <code>slider</code></td><td><code>0</code></td><td><code>-6..6</code>，步长 <code>1</code>；相对当前省略基准的显示单位偏移，<code>0</code> 使用基准</td><td><code>TextOmitOffset</code></td></tr><tr><td><code>VinaIcon.ui.TextOverflow</code><br>允许文本换行溢出</td><td><code>boolean</code> / <code>switch</code></td><td><code>false</code></td><td><code>false</code>：关闭；<code>true</code>：开启</td><td><code>AllowTextWrapOverflow</code></td></tr><tr><td><code>VinaIcon.ui.FadeTransition</code><br>渐隐效果</td><td><code>boolean</code> / <code>choice</code></td><td><code>false</code></td><td><code>false</code>：关闭（默认）；<code>true</code>：开启</td><td><code>FadeOutSwitch</code></td></tr><tr><td><code>VinaIcon.ui.IconBackground</code><br>图标背景</td><td><code>boolean</code> / <code>switch</code></td><td><code>false</code></td><td><code>false</code>：关闭；<code>true</code>：开启</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundColor</code><br>图标背景颜色</td><td><code>number</code> / <code>color</code></td><td>当前主题表面色</td><td>整数 <code>0..16777215</code>，COLORREF；<code>rgb(r, g, b)</code></td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundOpacity</code><br>图标背景不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>0.16</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundHoverOpacity</code><br>图标悬停不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>0.24</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundRadius</code><br>图标背景圆角</td><td><code>number</code> / <code>slider</code></td><td><code>8</code></td><td><code>0..128</code>，步长 <code>1</code></td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundExpand</code><br>图标背景扩展</td><td><code>number</code> / <code>slider</code></td><td><code>4</code></td><td><code>0..64</code>，步长 <code>1</code>；隐藏的旧兼容值，作为未单独设置 X/Y 时的初始值</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundExpandX</code><br>图标背景 X 扩展</td><td><code>number</code> / <code>slider</code></td><td>继承兼容扩展值（初始 <code>4</code>）</td><td><code>0..64</code>，步长 <code>1</code>；每侧扩展量，整个宽/高增加两倍该值</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundExpandY</code><br>图标背景 Y 扩展</td><td><code>number</code> / <code>slider</code></td><td>继承兼容扩展值（初始 <code>4</code>）</td><td><code>0..64</code>，步长 <code>1</code>；每侧扩展量，整个宽/高增加两倍该值</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBackgroundOffsetY</code><br>图标背景 Y 偏移</td><td><code>number</code> / <code>slider</code></td><td><code>0</code></td><td><code>-64..64</code>，步长 <code>1</code>；正值向下、负值向上，背景与边框一起移动</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBorder</code><br>图标边框</td><td><code>boolean</code> / <code>switch</code></td><td><code>false</code></td><td><code>false</code>：关闭；<code>true</code>：开启</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBorderColor</code><br>图标边框颜色</td><td><code>number</code> / <code>color</code></td><td>当前主题前景色</td><td>整数 <code>0..16777215</code>，COLORREF；<code>rgb(r, g, b)</code></td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBorderWidth</code><br>图标边框宽度</td><td><code>number</code> / <code>slider</code></td><td><code>0</code></td><td><code>0..8</code>，步长 <code>1</code>；<code>0</code> 不绘制独立边框</td><td>预设独立参数</td></tr><tr><td><code>VinaIcon.ui.IconBorderOpacity</code><br>图标边框不透明度</td><td><code>number</code> / <code>slider</code></td><td><code>0.18</code></td><td><code>0..1</code>，步长 <code>0.01</code></td><td>预设独立参数</td></tr></tbody></table><h2 id="行为" tabindex="-1">行为 <a class="header-anchor" href="#行为" aria-label="Permalink to &quot;行为&quot;">​</a></h2><table tabindex="0"><thead><tr><th>完整字段路径 / 界面项目</th><th>类型 / 控件</th><th>默认值</th><th>值、范围与选项</th><th>原生配置绑定</th></tr></thead><tbody><tr><td><code>Behavior.ui.AutoHideTitle</code><br>自动隐藏标题栏</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：自动常驻（默认）；<code>1</code>：隐藏并调整排版；<code>2</code>：仅隐藏；<code>3</code>：始终常驻</td><td><code>AutoHideTitleBar</code></td></tr><tr><td><code>Behavior.ui.QuickCollapse</code><br>快捷展开折叠</td><td><code>number</code> / <code>choice</code></td><td><code>1</code></td><td><code>0</code>：无；<code>1</code>：双击（默认）；<code>2</code>：单击</td><td><code>QuickExpandCollapse</code></td></tr><tr><td><code>Behavior.ui.CollapseDirection</code><br>折叠方向</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：自动（默认）；<code>1</code>：始终向上；<code>2</code>：始终向下</td><td><code>CollapseDirection</code></td></tr><tr><td><code>Behavior.ui.AutoHide</code><br>自动隐藏</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：关闭（默认）；<code>1</code>：自动淡化；<code>2</code>：自动折叠</td><td><code>AutoFade</code></td></tr><tr><td><code>Behavior.ui.InlineViewer</code><br>内联视图</td><td><code>number</code> / <code>choice</code></td><td><code>0</code></td><td><code>0</code>：关闭；<code>1</code>：启用</td><td><code>FolderOpenMode</code></td></tr><tr><td><code>Behavior.ui.SwipeSearch</code><br>上滑搜索</td><td><code>boolean</code> / <code>choice</code></td><td><code>true</code></td><td><code>false</code>：关闭；<code>true</code>：启用（默认）</td><td><code>SwipeUpSearchEnabled</code></td></tr></tbody></table><h2 id="显示条件和颜色来源" tabindex="-1">显示条件和颜色来源 <a class="header-anchor" href="#显示条件和颜色来源" aria-label="Permalink to &quot;显示条件和颜色来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>控件</th><th>何时显示</th></tr></thead><tbody><tr><td>背景不透明度</td><td>渲染层 <code>mode &gt; 0</code></td></tr><tr><td>系统圆角</td><td><code>mode &lt;= 2</code></td></tr><tr><td>窗口圆角</td><td>扩展层 <code>mode == 4</code>，或透明层 <code>mode == 3</code> 且非原生边框</td></tr><tr><td>静态材质层、窗口边框</td><td><code>mode &gt;= 3</code></td></tr><tr><td>阴影模糊、不透明度、X/Y 偏移</td><td>扩展层 <code>mode == 4</code></td></tr><tr><td>边框颜色、不透明度</td><td><code>mode &gt;= 3</code> 且边框选画布 <code>1</code> 或高光 <code>3</code></td></tr><tr><td>标题模糊</td><td><code>mode &lt;= 2</code> 或启用静态材质层</td></tr><tr><td>图标背景颜色、普通/悬停不透明度、圆角</td><td>开启图标背景</td></tr><tr><td>图标背景 X/Y 扩展、Y 偏移</td><td>开启图标背景或图标边框</td></tr><tr><td>图标边框颜色、宽度、不透明度</td><td>开启图标边框</td></tr><tr><td>旧 <code>IconBackgroundExpand</code></td><td>始终隐藏，供兼容读取</td></tr></tbody></table><p>颜色来源与颜色值是两项设置。普通背景/边框颜色编辑器的来源为主题 <code>0</code>、自定义 <code>1</code>；标题颜色为主题 <code>0</code>、标签色 <code>1</code>、自定义 <code>2</code>。这些来源不是额外的 <code>Pogget_Std.ui</code> 字段，不能作为 <code>parentValues</code> 的目标。用 <code>parentValues</code> 指定这三种颜色时，当前子预设默认选中“自定义”；后续在该子预设中切换来源仍可独立保存，不会改写父预设的来源选择。图标背景/边框颜色直接使用 COLORREF，没有来源选择页签。</p><h2 id="原生字段与自定义控件的关系" tabindex="-1">原生字段与自定义控件的关系 <a class="header-anchor" href="#原生字段与自定义控件的关系" aria-label="Permalink to &quot;原生字段与自定义控件的关系&quot;">​</a></h2><p><code>bind</code> 是原生配置的存储键，不是 <code>${}</code> 的引用路径。例如背景不透明度的存储键是 <code>bgAlpha</code>，对应的视图字段是 <code>Background.view.backgroundAlpha</code>，表达式应读取 <code>${Background.ui.BackgroundOpacity.value}</code>。不要把三者混写。</p><p><code>Background.view</code>、<code>Tag.view</code>、<code>VinaIcon.view</code>、<code>Behavior.view</code> 将这些 UI 值接入原生配置；修改 <code>ui</code> 默认值可以保留控件联动，直接覆盖 <code>view</code> 属性则由该表达式接管渲染结果。<code>IconBackground*</code>、<code>IconBorder*</code> 没有原生 <code>bind</code>，各收纳盒按所选预设单独保存。</p><h2 id="panel-与场景布局字段" tabindex="-1">Panel 与场景布局字段 <a class="header-anchor" href="#panel-与场景布局字段" aria-label="Permalink to &quot;Panel 与场景布局字段&quot;">​</a></h2><p><code>Panel</code> 是设置窗口的布局参数，不是新增个性化选项。尺寸、间距、字号、透明度等完整名称见<a href="./reference.html#设置面板-panel">面板布局表</a>。<code>ContainerFrame</code>、<code>TitleSurface</code>、<code>TitleButtons</code>、<code>TitleTag</code>、<code>TitleTabs</code>、<code>TitleSearch</code>、<code>FileIconSurface</code> 等组件的 <code>vars</code> 和 <code>view</code> 则描述具体绘制几何与效果；通用字段见<a href="./reference.html">接口参考</a>，各绘制阶段和高级布局的专用字段见<a href="./slots.html">绘制阶段与高级布局</a>。它们不是可放入 <code>parentValues</code> 的控件字段。</p><p>本页按当前 <code>Pogget_Std.vina</code> 与个性化面板核对（2026-11-17）。</p>',22)]))}const g=e(r,[["render",a]]);export{s as __pageData,g as default};
